SELECT id, title FROM post
WHERE status = 1 AND deleted = 0 AND id < #{id}
ORDER BY id DESC LIMIT 1

SELECT id, title FROM post
WHERE status = 1 AND deleted = 0 AND id > #{id}
ORDER BY id ASC LIMIT 1

SELECT COUNT(*) FROM post p
JOIN user_follow f ON f.followee_id = p.author_id AND f.follower_id = #{followerId}
WHERE p.status = 1 AND p.deleted = 0

SELECT p.*, c.name AS category_name, COALESCE(u.nickname, u.username) AS author_name, u.avatar AS author_avatar FROM post p LEFT JOIN category c ON c.id = p.category_id LEFT JOIN `user` u ON u.id = p.author_id WHERE p.deleted = 0 AND p.status = #{status}
AND p.title LIKE CONCAT('%', #{keyword}, '%')
AND p.author_id = #{authorId} ORDER BY p.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM post p
WHERE p.deleted = 0
AND p.status = #{status}

    AND p.title LIKE CONCAT('%', #{keyword}, '%')

AND p.author_id = #{authorId}

